import re,glob,os,sys
M={'info':'neutral','success':'positive','warning':'caution'}
tag=re.compile(r'<app-pill(?![\w-])((?:[^>"\']|"[^"]*"|\'[^\']*\')*?)(/?)>(?:\s*</app-pill>)?',re.S)
attr=re.compile(r'(\[?\w+\]?)\s*=\s*(?:"([^"]*)"|\'([^\']*)\')')
def neg(e):
    e=e.strip()
    if e=='true':return 'false'
    if e=='false':return 'true'
    if e.startswith('!') and not e.startswith('!='):
        r=e[1:].strip()
        if r.startswith('(') and r.endswith(')') and re.fullmatch(r'\((?:[^()]|\([^()]*\))*\)',r): r=r[1:-1]
        return r
    if re.fullmatch(r'[\w.?\[\]\'"()]+',e) : return '!'+e
    return '!('+e+')'
need=set()
def conv(m,path):
    body=m.group(1);vals={}
    rest=attr.sub(lambda a:vals.setdefault(a.group(1),a.group(2) if a.group(2) is not None else a.group(3)) and '' ,body)
    # vals may lose empty strings; recompute
    vals={a.group(1):(a.group(2) if a.group(2) is not None else a.group(3)) for a in attr.finditer(body)}
    rest=attr.sub('',body).strip()
    assert not rest,(path,rest)
    out=[];content=''
    if 'variant' in vals: out.append('tone="%s"'%M[vals['variant']])
    if '[variant]' in vals:
        e=vals['[variant]']
        if "'" in e: out.append('[tone]="%s"'%re.sub(r"'(info|success|warning)'",lambda x:"'%s'"%M[x.group(1)],e))
        else: out.append('[tone]="%s | pillTone"'%e); need.add(path)
    if 'label' in vals: content=vals['label']
    if '[label]' in vals: content='{{ %s }}'%vals['[label]']
    if '[disableTooltip]' in vals: out.append('[tooltip]="%s"'%neg(vals['[disableTooltip]']))
    if 'disableTooltip' in vals: raise Exception
    return '<app-pill %s>%s</app-pill>'%(' '.join(out),content)
for d in glob.glob('feature-*'):
    fs=glob.glob(d+'/*.html')+glob.glob(d+'/*.ts')
    for f in fs:
        s=open(f).read()
        if '<app-pill' not in s: continue
        n=tag.sub(lambda m:conv(m,d),s)
        open(f,'w').write(n)
    if d in need:
        t=glob.glob(d+'/*.ts')[0];s=open(t).read()
        s=s.replace('import { PillComponent,','import { PillTonePipe } from "../../lib/pill-tone.pipe";\nimport { PillComponent,',1)
        s=s.replace('imports: [ PillComponent,','imports: [ PillComponent, PillTonePipe,',1)
        open(t,'w').write(s)
EOF
python3 $TMPDIR/m.py; cat feature-1/*.html feature-92/*.ts | head -50; cd ../../..; npx ngc -p tsconfig.json | head -20

